package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.Cut;
import org.kanger.ContextSignedUnaryModelSearch.*;
import org.kanger.ContextSignedUnaryModelSearch.Result;
final class ContextSignedUnaryModelSearchMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Policy policy(){return new Policy(512,16,8,WORK,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy());}
 static Snapshot bind(boolean x,String text)throws Exception{return ContextSignedUnaryModelMatrix.bind(x,text);}
 static ContextSignedWitnessNativeBranch.Receipt branch(Snapshot x,Snapshot... fs){ContextSignedWitnessNativeBranch.Result r=ContextSignedWitnessNativeBranch.run(x,Arrays.asList(fs),ContextSignedWitnessNativeMatrix.policy());require(r.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED&&r.output!=null,r.phase+": "+r.reason);return r.output;}
 static Map<Cut,List<SemanticTermSnapshot>> bases(ContextSignedWitnessNativeBranch.Receipt b,SemanticTermSnapshot... points){Map<Cut,List<SemanticTermSnapshot>> out=new LinkedHashMap<>();out.put(Cut.of(b.x),new ArrayList<>(Arrays.asList(points)));for(Snapshot s:b.foreign)out.put(Cut.of(s),new ArrayList<>(Arrays.asList(points)));return out;}
 static void audit(Result r){require(r.status==Status.CONSTRUCTED_FINAL_UNARY&&r.output!=null,r.reason);ContextSignedUnaryBranchModel.Ledger l=r.output.ledger;ContextSignedUnaryModel.Ledger o=l.original.ledger;ContextSignedUnaryModelAudit.check(l.original,o.x,o.foreign,o.models,o.policy,WORK);ContextSignedUnaryBranchModelAudit.check(r.output,l.original,l.branch,l.extensions,l.policy,WORK);require(true,"fresh original and actual-final independent audits");}
 static void no(Result r,String why){require(r.status==Status.INCOMPLETE&&r.output==null,why+": no original-only prefix or conflict proof");}
 static void positive()throws Exception{
  SemanticTermSnapshot one=ContextSignedUnaryModelMatrix.one();ContextSignedWitnessNativeBranch.Receipt b=branch(bind(true,"!p(1);"));Result r=ContextSignedUnaryModelSearch.run(b,bases(b,one),policy());audit(r);require(r.tried==2&&r.originals==1&&r.extensionCandidates==1,"false original candidate refused before complete chain success");
  b=branch(bind(true,"!p(1); !@u p(u);"));r=ContextSignedUnaryModelSearch.run(b,bases(b,one),policy());audit(r);require(r.tried==4&&r.output.ledger.original.ledger.models.get(Cut.of(b.x)).truth.get("p").equals(Arrays.asList(true,true)),"all-admissible universal requires true OUTSIDE cell, not active-domain only");
  b=branch(bind(true,"!$u p(u)&&~q(u);"));r=ContextSignedUnaryModelSearch.run(b,bases(b,one),policy());audit(r);require(r.output.ledger.original.ledger.models.get(Cut.of(b.x)).witnesses.size()==1,"whole signed bundle uses one Source assignment");
  b=branch(bind(true,"!$u p(u); !$u q(u);"));r=ContextSignedUnaryModelSearch.run(b,bases(b,one),policy());audit(r);Collection<Integer> ws=r.output.ledger.original.ledger.models.get(Cut.of(b.x)).witnesses.values();require(ws.size()==2&&ws.stream().allMatch(v->v==0),"different existential Source tokens can coincide at SAME concrete value");
  b=branch(bind(true,"!$u p(u); !$u ~p(u);"));Map<Cut,List<SemanticTermSnapshot>> single=bases(b,one);r=ContextSignedUnaryModelSearch.run(b,single,policy());no(r,"one-point basis cannot realize both existential signs");require(r.tried==4&&r.reason.contains("space exhausted"),"complete fixed one-point candidate exhaustion is NOT theory inconsistency");r=ContextSignedUnaryModelSearch.run(b,bases(b,one,ContextSignedEligibilityMatrix.value(2)),policy());audit(r);ws=r.output.ledger.original.ledger.models.get(Cut.of(b.x)).witnesses.values();require(new HashSet<>(ws).size()==2,"same authentic branch has a verified model with explicit two-point basis");
  Snapshot x=bind(true,"!$u seed(u);");Snapshot a=bind(false,"!@u seed(u)->mark(u);");b=branch(x,a);r=ContextSignedUnaryModelSearch.run(b,bases(b,one),policy());audit(r);require(r.output.ledger.extensions.get(Cut.of(x)).truth.get("mark").get(0),"constructed original linked to generated new positive predicate extension");
  System.out.println("SIGNED_UNARY_MODEL_SEARCH_POSITIVE originalAndFinalAudited=true outsideUniversal=true correlatedBundle=true coincidentOrigins=true fixedBasisFailureNotRefutation=true");
 }
 static void topology()throws Exception{
  SemanticTermSnapshot one=ContextSignedUnaryModelMatrix.one();Snapshot x=bind(true,"!~anchor(1);"),a=bind(false,"!p(1);"),b=bind(false,"!~p(1);");for(boolean reverse:new boolean[]{false,true}){ContextSignedWitnessNativeBranch.Receipt branch=reverse?branch(x,b,a):branch(x,a,b);Result r=ContextSignedUnaryModelSearch.run(branch,bases(branch,one),policy());audit(r);Map<Cut,ContextSignedUnaryModel.Interpretation> models=r.output.ledger.original.ledger.models;require(models.get(Cut.of(a)).truth.get("p").get(0)&&!models.get(Cut.of(b)).truth.get("p").get(0),"independent opposite member truths in BOTH actual family orders");}
  Snapshot c=bind(false,"!~q(1);");Snapshot group=ContextProductionNativeBinding.trusted("model-search-trust",Arrays.asList(a,c),WORK);ContextSignedWitnessNativeBranch.Receipt branch=branch(x,group);Result r=ContextSignedUnaryModelSearch.run(branch,bases(branch,one),policy());audit(r);require(r.output.ledger.original.ledger.rows.size()==3&&r.output.ledger.original.ledger.models.size()==2,"one TRUST model retains BOTH physical member rows");
  Map<Cut,List<SemanticTermSnapshot>> input=bases(branch,one);r=ContextSignedUnaryModelSearch.run(branch,input,policy());audit(r);input.values().forEach(List::clear);require(!r.output.ledger.original.ledger.models.get(Cut.of(x)).points.isEmpty(),"mutable supplied basis lists detached from checked interpretations");
  System.out.println("SIGNED_UNARY_MODEL_SEARCH_TOPOLOGY independentOrders=2 trustedAllPhysicalRows=true detachedBases=true");
 }
 static void boundary()throws Exception{
  SemanticTermSnapshot one=ContextSignedUnaryModelMatrix.one();ContextSignedWitnessNativeBranch.Receipt b=branch(bind(true,"!p(1);"));Map<Cut,List<SemanticTermSnapshot>> basis=bases(b,one);Result r=ContextSignedUnaryModelSearch.run(b,basis,new Policy(1,16,8,WORK,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy()));no(r,"original candidate cap");require(r.tried==1&&r.originals==0&&r.reason.contains("candidate limit"),"no original proof from all-false first candidate");
  no(ContextSignedUnaryModelSearch.run(b,Collections.emptyMap(),policy()),"missing cut basis");no(ContextSignedUnaryModelSearch.run(b,bases(b,ContextSignedEligibilityMatrix.value(2)),policy()),"unnamed original constant");no(ContextSignedUnaryModelSearch.run(b,bases(b,one,one),policy()),"semantically duplicate named points");no(ContextSignedUnaryModelSearch.run(b,basis,new Policy(64,1,8,WORK,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy())),"truth cell bound counts outside");no(ContextSignedUnaryModelSearch.run(b,basis,new Policy(64,16,8,1,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy())),"construction work limit");no(ContextSignedUnaryModelSearch.run(b,basis,new Policy(64,16,8,WORK,new ContextSignedUnaryModel.Policy(64,16,64,1),ContextSignedUnaryExtensionSearchMatrix.policy())),"original auditor work bound");
  ContextSignedWitnessNativeBranch.Receipt witness=branch(bind(true,"!$u p(u);"));no(ContextSignedUnaryModelSearch.run(witness,bases(witness,one),new Policy(64,16,0,WORK,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy())),"whole original Source witness bound");
  Snapshot x=bind(true,"!$u seed(u);"),a=bind(false,"!@u seed(u)->mark(u);");ContextSignedWitnessNativeBranch.Receipt linked=branch(x,a);ContextSignedUnaryExtensionSearch.Policy shortExtension=new ContextSignedUnaryExtensionSearch.Policy(1,16,8,WORK,ContextSignedUnaryBranchMatrix.policy());r=ContextSignedUnaryModelSearch.run(linked,bases(linked,one),new Policy(64,16,8,WORK,ContextSignedUnaryModelMatrix.policy(),shortExtension));no(r,"valid original candidates cannot bypass failed final extension construction");require(r.originals>0&&r.extensionCandidates==r.originals,"all accepted original candidates go through mandatory bounded final chain");
  no(ContextSignedUnaryModelSearch.run(linked,bases(linked,one),new Policy(64,16,8,WORK,new ContextSignedUnaryModel.Policy(1,16,64,WORK),ContextSignedUnaryExtensionSearchMatrix.policy())),"whole physical original row bound before candidates");no(ContextSignedUnaryModelSearch.run(b,bases(b,one,ContextSignedEligibilityMatrix.value(2)),new Policy(64,16,8,WORK,new ContextSignedUnaryModel.Policy(64,1,64,WORK),ContextSignedUnaryExtensionSearchMatrix.policy())),"explicit named-basis point cap");
  Object old=ContextSignedWitnessBarrierMatrix.replace(b.termination.result,"output",b.start);try{no(ContextSignedUnaryModelSearch.run(b,basis,policy()),"stale actual final scope");}finally{ContextSignedWitnessBarrierMatrix.replace(b.termination.result,"output",old);}audit(ContextSignedUnaryModelSearch.run(b,basis,policy()));no(ContextSignedUnaryModelSearch.run(null,basis,policy()),"missing actual branch");
  try{new Policy(513,16,8,WORK,ContextSignedUnaryModelMatrix.policy(),ContextSignedUnaryExtensionSearchMatrix.policy());throw new AssertionError("candidate hard cap");}catch(IllegalArgumentException expected){require(true,"hard original candidate maximum");}
  System.out.println("SIGNED_UNARY_MODEL_SEARCH_BOUNDARY originalOnlyNeverPublished=true fixedBasisAndWorkBounds=true staleScopeRejected=true noConflictFromFailure=true");
 }
}
